#include "markdownmay/export/pdf_writer.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iterator>
int RunPdfWriterTests(){using namespace markdownmay;using namespace markdownmay::exporting;std::string source="# 中文标题\n\n[链接](https://example.com) 与 $a+b$。\n\n```mermaid\nA-->B\n```\n";for(int i=0;i<100;++i)source+="分页正文。\n\n";document::DocumentSession session(source);auto snapshot=session.snapshot();auto full=BuildExportDocument(snapshot,snapshot.source_revision,ExportScope::full,ExportFormat::pdf);if(!full.is_ok())return 50;const bool keep=std::filesystem::exists("tmp/pdfs/.keep");auto dir=keep?std::filesystem::path("tmp/pdfs/fixture"):std::filesystem::temp_directory_path()/("markdownmay-pdf-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(dir);auto path=dir/"full.pdf";auto result=ExportPdf(full.value(),path);if(result!=ErrorCode::ok)return 51;if(ValidatePdf(path)!=ErrorCode::ok)return 54;std::ifstream in(path,std::ios::binary);std::string pdf{std::istreambuf_iterator<char>(in),{}};if(!pdf.starts_with("%PDF-1.7")||pdf.find("/Count ")==std::string::npos||pdf.find("/Subtype /Link")==std::string::npos||pdf.find("/ToUnicode")==std::string::npos)return 52;CancellationSource cancelled;cancelled.cancel();if(ExportPdf(full.value(),dir/"cancelled.pdf",cancelled.token())!=ErrorCode::export_cancelled)return 53;if(!keep){std::error_code ignored;std::filesystem::remove_all(dir,ignored);}return 0;}
